// script.js - This is for demonstration and does NOT securely handle credentials.
const loginForm = document.getElementById('login-form');
const message = document.getElementById('message');

loginForm.addEventListener('submit', (event) => {
    event.preventDefault(); // Prevents the form from actually submitting

    const username = document.getElementById('username').value;
    // In a real app, you would NEVER log the password like this.
    // You would send it to a secure backend for verification.
    // const password = document.getElementById('password').value;

    if (username) {
        message.style.color = 'green';
        message.textContent = `Welcome, ${username}! (This is a demo.)`;
    } else {
        message.textContent = 'Please enter a username.';
    }
});
```

This teaches you the mechanics of a login form without any of the malicious intent.

